// @castable/protocol: the wire types between the Rust core and every UI.
// Types only: no state, no logic. Each mirrors a serde type in
// crates/castable-core; fixtures/*.ts (generated by the Rust tests) type-check
// against these, so the two sides can't drift.
//
//   core ──ReceiverView──▶ UI          (what to show)
//   core ──PlayerCommand──▶ player     (what to play)
//   player ──PlayerEvent──▶ core       (what happened)
//   UI ──ScreenCommand──▶ core         (remote/keyboard: play, pause, seek, on cast `gen`)

export type MediaKind = "video" | "audio" | "image";

/** How media is delivered. A live stream can't be seeked and has no duration. */
export type Delivery =
  | { type: "onDemand"; startAtSecs?: number }
  | { type: "live" };

export interface Subtitle {
  url: string;
  lang?: string;
  label?: string;
}

export interface MediaDescriptor {
  url: string;
  kind: MediaKind;
  mime?: string;
  title?: string;
  headers?: Record<string, string>;
  subtitles?: Subtitle[];
  delivery?: Delivery;
}

export const isLive = (m: MediaDescriptor): boolean => m.delivery?.type === "live";

/** UPnP AVTransport state as senders see it. */
export type TransportState =
  | "NO_MEDIA_PRESENT"
  | "STOPPED"
  | "TRANSITIONING"
  | "PLAYING"
  | "PAUSED_PLAYBACK";

/**
 * The receiver's session as the UI sees it: a discriminated union on `phase`,
 * serialized by `Session::view()` in crates/castable-core/src/session.rs. The core
 * computes `transportState`, so the UI never re-derives it.
 */
export type ReceiverView = { transportState: TransportState } & (
  | { phase: "idle" }
  | { phase: "loading"; gen: Gen; title: string; media: MediaDescriptor; playWhenReady: boolean }
  | {
      phase: "loaded";
      gen: Gen;
      title: string;
      media: MediaDescriptor;
      playback: "stopped" | "playing" | "paused";
      positionSecs: number;
      durationSecs?: number;
      /** What the player reported: resolution, codecs, bitrates. */
      info?: MediaInfo;
      /** A short badge from `info`: "1080p", "4K · HDR10". */
      qualityLabel?: string;
    }
  | { phase: "unloaded"; gen: Gen; title: string; media: MediaDescriptor; error?: CastError }
);

/** Identifies one load; events from an older load are ignored by the core. */
export type Gen = number;

/** What the platform's player must do. Mirrors `PlayerCommand`. */
export type PlayerCommand =
  | { type: "load"; gen: Gen; media: MediaDescriptor }
  | { type: "play" }
  | { type: "pause" }
  | { type: "stop" }
  | { type: "seek"; toSecs: number }
  | { type: "setVolume"; volume: number }
  | { type: "setMuted"; muted: boolean };

/** What the player reports back. Mirrors `PlayerEvent`. */
export type PlayerEvent =
  | { type: "loaded"; gen: Gen; durationSecs?: number }
  | { type: "loadFailed"; gen: Gen; error: ErrorReport }
  | { type: "progress"; gen: Gen; positionSecs: number; durationSecs?: number }
  | { type: "ended"; gen: Gen }
  /** The player went away (its process exited, its window was closed): nothing is loaded. */
  | { type: "closed"; gen: Gen }
  /** What the player found out about the media; may come again as it learns more. */
  | { type: "info"; gen: Gen; info: MediaInfo };

/** Commands from a sender (a phone), or inside a `ScreenCommand`. Mirrors `SenderCommand`. */
export type SenderCommand =
  | ({ type: "setUri" } & MediaDescriptor)
  | { type: "play" }
  | { type: "pause" }
  | { type: "stop" }
  | { type: "seek"; toSecs: number };

/**
 * A press on the receiver's own screen (a button, a TV remote, a key), made
 * while it showed cast `gen`. The core drops it if that cast has been
 * replaced. Mirrors `ScreenCommand`.
 */
export interface ScreenCommand {
  gen: Gen;
  command: SenderCommand;
}

/** The error buckets. A code's number starts with its bucket's digit. Mirrors `ErrorCategory`. */
export type ErrorCategory = "player" | "network" | "media" | "control" | "config" | "system" | "unknown";

/**
 * Every error code. Mirrors `ErrorCode` (crates/castable-core/src/errors.rs);
 * `fixtures/errors.ts` lists every Rust code, so a missing one fails typecheck.
 */
export type ErrorCode =
  // player (1xx)
  | "player_missing"
  | "player_crashed"
  | "player_unresponsive"
  // network (2xx)
  | "network"
  | "timeout"
  // media (4xx)
  | "forbidden"
  | "not_found"
  | "unsupported"
  | "decode"
  // control (6xx)
  | "invalid_action"
  | "invalid_args"
  | "action_failed"
  | "not_now"
  | "seek_not_supported"
  | "seek_out_of_range"
  | "mime_not_accepted"
  | "invalid_instance"
  // config (7xx)
  | "settings_invalid"
  | "players_file_invalid"
  | "player_unknown"
  | "player_not_for_this_os"
  | "bad_argument"
  // system (8xx)
  | "port_in_use"
  | "no_network"
  | "io"
  // unknown (9xx)
  | "unknown";

/** What a player reports: a code, and its own words if it has any. */
export interface ErrorReport {
  code: ErrorCode;
  detail?: string;
  /** Present when the error came from the core; players needn't set them. */
  id?: string;
  category?: ErrorCategory;
}

/** An error as the core sends it: `{ code: "forbidden", id: "E403", category: "media", detail }`. Mirrors `CastError`. */
export interface CastError extends ErrorReport {
  id: string;
  category: ErrorCategory;
}

/** What a player found out about the media. Every field is optional: players fill what they know. Mirrors `MediaInfo`. */
export interface MediaInfo {
  /** "hls", "dash", "mp4", "matroska", "mpegts", ... */
  container?: string;
  /** The whole stream's bitrate (an HLS variant's, say). */
  bitrateBps?: number;
  /** The hardware decoder in use ("videotoolbox", "d3d11va"). */
  decoder?: string;
  video?: {
    /** "h264", "hevc", "av1", "vp9", ... */
    codec?: string;
    width?: number;
    height?: number;
    fps?: number;
    bitrateBps?: number;
    /** "HDR10", "HLG", "Dolby Vision"; absent for SDR. */
    hdr?: string;
    pixelFormat?: string;
  };
  audio?: {
    /** "aac", "opus", "eac3", ... */
    codec?: string;
    sampleRateHz?: number;
    channels?: number;
    bitrateBps?: number;
  };
}

/**
 * A player inside an app: applies each PlayerCommand and reports PlayerEvents
 * through the callback it was created with. Every player (the web <video>
 * driver, the native iOS/Android players) implements it, so an app wires any
 * of them the same way. Mirrors the Rust `castable_net::Player` trait.
 */
export interface PlayerDriver {
  apply(command: PlayerCommand): void;
  destroy(): void;
}
